class Solution {
  public int countSpecialIntegers(int[] nums) {
    java.util.HashMap<Integer, List<Integer>> positions = new java.util.HashMap<>();
    for (int i = 0; i < nums.length; i++)
      positions.computeIfAbsent(nums[i], k -> new ArrayList<>()).add(i);
    int count = 0;
    for (List<Integer> p : positions.values()) {
      if (p.size() < 3) continue;
      int step = p.get(1) - p.get(0);
      boolean ok = true;
      for (int i = 2; i < p.size() && ok; i++) if (p.get(i) - p.get(i - 1) != step) ok = false;
      if (ok) count++;
    }
    return count;
  }
}
